import { loadFont } from "@remotion/google-fonts/Sora";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// SOLARE Energia Solar. Motion vertical de 30 s sobre o roteiro do cliente (reflexão → conta alta e calor → a solução → orçamento).
// Identidade do logo: azul-marinho #01244E, âmbar #FDA904, verde #024D15, sobre branco. Tom lido: sério e acolhedor (casa, família).
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos objetos (sol, contas, casa).
// No trecho do problema o visual é genérico (contas desenhadas, a conta ilustrativa que o cliente mandou); a marca só entra em 14 s.
// Tempos = tempos do roteiro (provisórios, sem locução ainda). Quando a voz chegar, WARP leva o tempo da voz para estes tempos,
// âncora por âncora ([tempo da voz, tempo daqui]), sem reescrever as cenas.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const SLR_FPS = 30;
const LEAD = 0.15;
export const SLR_FRAMES = Math.round(41.3 * SLR_FPS);
// locução v1 (ElevenLabs, 40,2 s): [tempo da voz, tempo da cena]
const WARP = [[-0.15, -0.15], [0.57, 0.55], [1.11, 1.1], [1.9, 1.7], [2.1, 1.8], [3.84, 3.1], [4.66, 4.2], [6.2, 5.3], [6.75, 5.75], [8.05, 7.0], [9.65, 7.95], [10.29, 8.75], [10.97, 9.75], [12.3, 10.55], [12.95, 10.75], [14.23, 11.9], [14.73, 12.25], [15.29, 12.5], [16.31, 13.2], [17.45, 14.0], [19.6, 15.55], [20.15, 15.75], [20.95, 16.3], [21.5, 16.7], [21.95, 17.5], [23.75, 18.7], [24.45, 19.2], [25.15, 20.15], [25.73, 20.3], [26.1, 20.75], [27.0, 22.0], [27.6, 22.5], [28.3, 23.4], [29.36, 23.95], [30.0, 24.4], [30.8, 25.2], [32.6, 26.2], [34.62, 27.1], [35.5, 27.6], [37.0, 28.5], [41.3, 30.0]] as [number, number][] | null;
// tempo real do vídeo, para o que gira ou pulsa sem depender da fala (o fecho dura bem mais que no roteiro)
const Real = React.createContext(0);
// versão de 30 s: a mesma locução cortada nas pausas (src/voz-1-30s.wav), sem "Enquanto isso", "e economizar na conta de luz",
// "Faça-nos uma visita ou" e o telefone ditado. A cena do orçamento começa já no documento (SKIP) e o fecho mostra o telefone antes do slogan.
export const SLR_30_FRAMES = Math.round(30.0 * SLR_FPS);
const WARP30 = [[-0.15, -0.15], [0.57, 0.55], [1.11, 1.1], [1.7, 1.7], [1.85, 1.8], [3.59, 3.1], [4.41, 4.2], [5.95, 5.3], [6.5, 5.75], [7.5, 7.0], [9.1, 7.95], [9.74, 8.75], [10.42, 9.75], [10.8, 10.55], [10.97, 10.75], [12.25, 11.9], [12.75, 12.25], [13.31, 12.5], [14.33, 13.2], [15.47, 14.0], [17.62, 15.55], [18.17, 15.75], [18.97, 16.3], [19.3, 16.7], [19.6, 17.5], [19.95, 18.7], [20.65, 19.2], [21.35, 20.15], [21.93, 20.3], [22.3, 20.75], [23.05, 22.0], [24.07, 22.6], [24.71, 23.05], [25.45, 23.85], [29.85, 28.25]] as [number, number][];
const SKIP = 1.35;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const WHITE = "#FFFFFF";
const NAVY = "#01244E";
const AMBER = "#FDA904";
const GREEN = "#0A6A22";
const RED = "#D12B2B";
const SKY = "#F1F6FD";
const WARM = "#FFF2DC";
const LINE = "#DCE4F0";
const SHADOW = "0 30px 70px rgba(1,36,78,0.14), 0 4px 14px rgba(1,36,78,0.07)";
const SHADOW_D = "0 44px 90px rgba(0,0,0,0.38), 0 6px 18px rgba(0,0,0,0.2)";

// trocas de cena
const T1 = 7.0, T2 = 10.6, T3 = 14.0, T4 = 15.55, T5 = 18.7, T6 = 22.0, T7L = 25.2, T7 = T7L;

// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 18 + o * 14).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};

// linhas de título; a linha de destaque vem numa faixa de cor chapada
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; hlBg?: string; hlColor?: string }> = ({ t, items, size, top, color = NAVY, out, hlBg = AMBER, hlColor = NAVY }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.1 }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.04em", whiteSpace: "nowrap", color: hl ? hlColor : color, ...(hl ? { background: hlBg, padding: `${size * 0.04}px ${size * 0.26}px ${size * 0.1}px`, borderRadius: size * 0.24 } : {}), ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// ───────── desenhos ─────────
const IcoBolt: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><path d="M13.5 2L4.5 13.5h6L9.5 22l9.5-12h-6.2z" /></svg>
);
// sol do logo: disco e raios em triângulo
const Sun: React.FC<{ r: number; rot: number; rays?: number; len?: number; color?: string }> = ({ r, rot, rays = 12, len = 0.62, color = AMBER }) => {
  const R = r * (1 + len) + 4;
  return (
    <svg width={R * 2} height={R * 2} viewBox={`${-R} ${-R} ${R * 2} ${R * 2}`} style={{ display: "block", overflow: "visible" }}>
      <g transform={`rotate(${rot.toFixed(2)})`}>
        {[...Array(rays)].map((_, i) => (
          <path key={i} d={`M${r * 1.12} ${-r * 0.1} L${r * (1 + len)} 0 L${r * 1.12} ${r * 0.1} Z`} fill={color} transform={`rotate(${(i * 360) / rays})`} />
        ))}
      </g>
      <circle r={r} fill={color} />
    </svg>
  );
};
// conta de luz genérica, sem marca: todas iguais
const Bill: React.FC<{ w: number }> = ({ w }) => {
  const h = w * 1.3;
  return (
    <div style={{ width: w, height: h, borderRadius: w * 0.07, background: WHITE, border: `2px solid ${LINE}`, boxSizing: "border-box", position: "relative", overflow: "hidden", boxShadow: "0 18px 40px rgba(1,36,78,0.13)" }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: h * 0.2, background: "#9AA6B8", display: "flex", alignItems: "center", gap: w * 0.04, paddingLeft: w * 0.08 }}>
        <div style={{ width: w * 0.15, height: w * 0.15, borderRadius: w, background: WHITE, display: "flex", alignItems: "center", justifyContent: "center" }}><IcoBolt s={w * 0.1} c="#9AA6B8" /></div>
        <span style={{ fontFamily: F, fontWeight: 700, fontSize: w * 0.085, color: WHITE, letterSpacing: "0.02em" }}>CONTA DE LUZ</span>
      </div>
      <div style={{ position: "absolute", left: w * 0.08, right: w * 0.08, top: h * 0.27, height: h * 0.2, borderRadius: w * 0.04, background: "#FBE9E9", display: "flex", alignItems: "center", paddingLeft: w * 0.06, gap: w * 0.04 }}>
        <span style={{ fontFamily: F, fontWeight: 800, fontSize: w * 0.15, color: RED, letterSpacing: "-0.03em" }}>R$</span>
        <div style={{ width: w * 0.4, height: w * 0.1, borderRadius: w * 0.03, background: RED }} />
      </div>
      {[0.55, 0.64, 0.73, 0.82].map((y, i) => (
        <div key={i} style={{ position: "absolute", left: w * 0.08, top: h * y, width: w * (i % 2 ? 0.56 : 0.84), height: w * 0.045, borderRadius: w * 0.03, background: "#DDE3EC" }} />
      ))}
    </div>
  );
};
// conta ilustrativa que o cliente mandou, com câmera: [tempo, foco x, foco y, zoom] (foco em fração do cartão)
type Cam = [number, number, number, number];
const BillShot: React.FC<{ t: number; src: string; w: number; cam: Cam[]; r?: number }> = ({ t, src, w, cam, r = 34 }) => {
  const h = (w * 984) / 694;
  const ts = cam.map((c) => c[0]);
  const at = (j: number) => (cam.length > 1 ? interpolate(t, ts, cam.map((c) => c[j]), { ...cl, easing: INOUT }) : cam[0][j]);
  const z = at(3);
  const x = Math.min(0, Math.max(w - w * z, w / 2 - at(1) * w * z)), y = Math.min(0, Math.max(h - h * z, h / 2 - at(2) * h * z));
  return (
    <div style={{ width: w, height: h, borderRadius: r, overflow: "hidden", background: WHITE, position: "relative" }}>
      <Img src={staticFile(`solar/${src}.jpg`)} style={{ position: "absolute", left: 0, top: 0, width: w, height: h, maxWidth: "none", transformOrigin: "0 0", transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${z.toFixed(4)})` }} />
    </div>
  );
};
const Note: React.FC<{ top: number; o: number; color: string }> = ({ top, o, color }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, textAlign: "center", fontFamily: F, fontWeight: 500, fontSize: 30, color, opacity: o, letterSpacing: "0.01em" }}>valores ilustrativos</div>
);

// ───────── cena 1 · reflexão: três batidas de tela cheia e a pergunta, com as contas de cada ano empilhando ─────────
const BEATS: [string, number, string, string][] = [["Faça uma", 0.0, NAVY, WHITE], ["reflexão", 0.55, AMBER, NAVY], ["comigo", 1.1, WHITE, NAVY]];
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const Q = 1.7;
  const N = 8;
  const land = (i: number) => 2.05 + i * 0.4;
  const years = [...Array(N)].filter((_, i) => t >= land(i) + 0.18).length;
  const sun = k(t, 5.3, 0.9);
  const tag = pop(t, 5.75, 0.5);
  return (
    <AbsoluteFill style={{ background: WHITE }}>
      {t >= Q - 0.05 ? (
        <>
          <Lines t={t} top={230} size={78} items={[["Quanto você poderia", 1.8], ["ter economizado", 3.1, true], ["ao longo dos anos?", 4.2]]} />
          <div style={{ position: "absolute", inset: 0, transformOrigin: "540px 1200px", transform: `scale(${(0.95 + 0.1 * lin(t, Q, T1)).toFixed(4)})` }}>
            {/* o sol nasce atrás da pilha em "energia solar" */}
            <div style={{ position: "absolute", left: 540, top: 1190, width: 0, height: 0, opacity: Math.min(1, sun * 2) }}>
              <div style={{ position: "absolute", transform: `translate(-50%, -50%) translateY(${((1 - sun) * 420).toFixed(1)}px) scale(${(0.6 + 0.4 * sun).toFixed(3)})` }}><Sun r={300} rot={t * 14} /></div>
            </div>
            {/* uma conta por ano */}
            {[...Array(N)].map((_, i) => {
              const a = land(i);
              if (t < a) return null;
              const e = k(t, a, 0.42);
              const side = i % 2 ? 1 : -1;
              const x = side * (30 + i * 6), y = 990 - i * 20, r = side * (5 + (i % 3) * 2.5) + Math.sin(t * 1.9 + i) * 1.4;
              return (
                <div key={i} style={{ position: "absolute", left: 540 - 215 + x * e + side * (1 - e) * 520, top: y - (1 - e) * 1250 + Math.sin(t * 2.2 + i * 1.3) * 6, zIndex: i + 1, opacity: Math.min(1, e * 5), transform: `rotate(${(r * e + (1 - e) * side * 38).toFixed(2)}deg) scale(${((0.8 + 0.2 * e) * (1 - 0.2 * sun)).toFixed(4)})`, transformOrigin: "50% 60%" }}>
                  <Bill w={430} />
                </div>
              );
            })}
            {/* contador de anos */}
            <div style={{ position: "absolute", left: 0, right: 0, top: 730, display: "flex", justifyContent: "center", zIndex: 20 }}>
              <div style={{ padding: "16px 44px 20px", borderRadius: 999, background: NAVY, fontFamily: F, fontWeight: 700, fontSize: 56, color: WHITE, letterSpacing: "-0.02em", opacity: Math.min(1, pop(t, land(0) + 0.15, 0.35) * 2) * (1 - lin(t, 5.25, 5.5)), transform: `scale(${(1 + 0.16 * [...Array(N)].reduce((m: number, _, i) => Math.max(m, t >= land(i) + 0.18 ? 1 - k(t, land(i) + 0.18, 0.3) : 0), 0)).toFixed(4)})` }}>
                {years} {years === 1 ? "ano" : "anos"}
              </div>
            </div>
          </div>
          <div style={{ position: "absolute", left: 0, right: 0, top: 1650, display: "flex", justifyContent: "center", zIndex: 30 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 18, padding: "22px 46px 26px 36px", borderRadius: 999, background: NAVY, boxShadow: SHADOW, opacity: Math.min(1, tag * 2), transform: `scale(${(0.5 + 0.5 * tag).toFixed(3)})` }}>
              <Sun r={17} rot={t * 40} rays={8} len={0.7} />
              <span style={{ fontFamily: F, fontWeight: 700, fontSize: 52, color: WHITE, letterSpacing: "-0.03em" }}>com energia solar</span>
            </div>
          </div>
        </>
      ) : null}
      {/* abertura: uma palavra por batida, cada uma numa cor da marca */}
      {BEATS.map(([w, at, bg, fg], i) => {
        const end = i < 2 ? BEATS[i + 1][1] : Q;
        if (t < at || t >= end + 0.22) return null;
        const e = k(t, at, 0.3);
        const o = i === 2 ? lin(t, end - 0.02, end + 0.2) : 0;
        return (
          <AbsoluteFill key={i} style={{ background: bg, alignItems: "center", justifyContent: "center", opacity: 1 - o, clipPath: i > 0 ? `inset(0 0 ${((1 - k(t, at, 0.22)) * 100).toFixed(2)}% 0)` : undefined }}>
            <div style={{ fontFamily: F, fontWeight: 800, fontSize: 168, letterSpacing: "-0.05em", color: fg, transform: `scale(${(1.3 - 0.3 * e + 0.05 * lin(t, at, end)).toFixed(4)})`, filter: `blur(${((1 - e) * 14).toFixed(1)}px)` }}>{w}</div>
            {i === 2 ? <div style={{ width: 620 * k(t, at + 0.12, 0.35), height: 18, borderRadius: 9, background: AMBER, marginTop: 6 }} /> : null}
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

// ───────── cena 2a · a conta alta (a ilustrativa do cliente), com a câmera indo no total e no histórico subindo ─────────
const Conta: React.FC<{ t: number }> = ({ t }) => {
  const inn = pop(t, T1 + 0.1, 0.6);
  const up = pop(t, 8.3, 0.45);
  const W = 620;
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      <div style={{ position: "absolute", left: 540 - 800, top: 1180 - 800, width: 1600, height: 1600, background: `radial-gradient(closest-side, rgba(209,43,43,${(0.26 + 0.05 * Math.sin(t * 2)).toFixed(3)}), rgba(209,43,43,0))` }} />
      <Lines t={t} top={220} size={78} color={WHITE} hlBg={RED} hlColor={WHITE} items={[["E quanto ainda", T1 + 0.15], ["vai pagar", 7.95, true], ["nos próximos anos…", 8.75]]} />
      <div style={{ position: "absolute", left: 540 - W / 2, top: 730, opacity: Math.min(1, inn * 2), transform: `translateY(${((1 - inn) * 260 + Math.sin(t * 1.7) * 7).toFixed(1)}px) rotate(${((1 - inn) * -7 + Math.sin(t * 1.3) * 0.7).toFixed(2)}deg) scale(${(0.7 + 0.3 * inn).toFixed(4)})` }}>
        <div style={{ borderRadius: 34, boxShadow: SHADOW_D }}>
          <BillShot t={t} src="conta-antes" w={W} cam={[[T1 + 0.2, 0.5, 0.5, 1], [7.9, 0.5, 0.5, 1], [8.5, 0.33, 0.36, 1.5], [9.25, 0.33, 0.36, 1.6], [9.75, 0.5, 0.8, 1.1], [T2, 0.5, 0.8, 1.2]]} />
        </div>
        {/* subindo */}
        <div style={{ position: "absolute", right: -46, top: -46, width: 132, height: 132, borderRadius: 66, background: RED, border: `8px solid ${NAVY}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, up * 2), transform: `scale(${(0.3 + 0.7 * up).toFixed(3)}) translateY(${(-9 * Math.abs(Math.sin(t * 5))).toFixed(1)}px)` }}>
          <svg width={64} height={64} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={3.4} strokeLinecap="round" strokeLinejoin="round"><path d="M12 20V4" /><path d="M5 11l7-7 7 7" /></svg>
        </div>
      </div>
      <Note top={1666} o={0.6 * k(t, 7.6, 0.5)} color={WHITE} />
    </AbsoluteFill>
  );
};

// ───────── cena 2b · dia quente: o termômetro sobe e o ar-condicionado é desligado para economizar ─────────
const Calor: React.FC<{ t: number }> = ({ t }) => {
  const rt = React.useContext(Real);
  const OFF = 12.25;
  const rise = k(t, T2 + 0.05, 0.8);
  const temp = 0.22 + 0.7 * interpolate(t, [T2 + 0.3, 13.3], [0, 1], { ...cl, easing: Easing.out(Easing.quad) });
  const ac = pop(t, T2 + 0.25, 0.55);
  const off = k(t, OFF, 0.35);
  const chip = pop(t, OFF + 0.1, 0.4);
  const shake = t > OFF ? Math.sin((t - OFF) * 40) * 9 * Math.max(0, 1 - (t - OFF) / 0.35) : 0;
  return (
    <AbsoluteFill style={{ background: WARM }}>
      <Lines t={t} top={210} size={76} items={[["Nos dias mais quentes", T2 + 0.15], ["você economiza", 11.9], ["até no conforto", 12.5, true], ["da sua família", 13.2]]} />
      {/* sol grande subindo por baixo */}
      <div style={{ position: "absolute", left: 540, top: 1700, width: 0, height: 0 }}>
        <div style={{ position: "absolute", transform: `translate(-50%, -50%) translateY(${((1 - rise) * 600).toFixed(1)}px) scale(${(1 + 0.04 * Math.sin(rt * 3.4) + 0.12 * lin(t, T2, T3)).toFixed(4)})` }}><Sun r={330} rot={rt * 24} rays={14} len={0.5} /></div>
      </div>
      {/* ondas de calor */}
      <svg width={1080} height={420} viewBox="0 0 1080 420" style={{ position: "absolute", left: 0, top: 1000 }}>
        {[390, 540, 690].map((x, i) => (
          <path key={i} d={`M${x} 400 q -34 -50 0 -100 t 0 -100 t 0 -100 t 0 -100`} fill="none" stroke={AMBER} strokeWidth={12} strokeLinecap="round" strokeDasharray="150 260" strokeDashoffset={-(rt * 330 + i * 130)} opacity={0.75 * rise} />
        ))}
      </svg>
      {/* termômetro */}
      <div style={{ position: "absolute", left: 150, top: 810, width: 130, height: 500, opacity: Math.min(1, ac * 2), transform: `translateX(${((1 - ac) * -160).toFixed(1)}px) rotate(${(Math.sin(rt * 2.6) * 2.5).toFixed(2)}deg)` }}>
        <div style={{ position: "absolute", left: 37, top: 0, width: 56, height: 400, borderRadius: 28, background: WHITE, border: `7px solid ${NAVY}`, boxSizing: "border-box", overflow: "hidden" }}>
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: `${(temp * 100).toFixed(1)}%`, background: RED }} />
        </div>
        <div style={{ position: "absolute", left: 5, top: 370, width: 120, height: 120, borderRadius: 60, background: RED, border: `7px solid ${NAVY}`, boxSizing: "border-box", transform: `scale(${(1 + 0.07 * Math.sin(rt * 9)).toFixed(4)})` }} />
        {[60, 130, 200, 270].map((y) => <div key={y} style={{ position: "absolute", left: 104, top: y, width: 26, height: 7, borderRadius: 4, background: NAVY }} />)}
      </div>
      {/* ar-condicionado */}
      <div style={{ position: "absolute", left: 350, top: 830, width: 580, opacity: Math.min(1, ac * 2), transform: `translateY(${((1 - ac) * -140).toFixed(1)}px) translateX(${shake.toFixed(1)}px) translateY(${(Math.sin(rt * 2.2) * 8).toFixed(1)}px) scale(${(0.8 + 0.2 * ac).toFixed(4)})` }}>
        <div style={{ height: 190, borderRadius: 38, background: WHITE, border: `7px solid ${NAVY}`, boxSizing: "border-box", position: "relative", boxShadow: SHADOW }}>
          <div style={{ position: "absolute", left: 40, right: 40, bottom: 34, height: 14, borderRadius: 7, background: NAVY, transform: `scaleY(${(1 + 1.6 * (1 - off)).toFixed(3)})` }} />
          <div style={{ position: "absolute", left: 40, right: 200, top: 46, height: 10, borderRadius: 5, background: LINE }} />
          <div style={{ position: "absolute", right: 44, top: 36, width: 30, height: 30, borderRadius: 15, background: off > 0.5 ? "#B5BDC9" : "#27B45A" }} />
        </div>
        <svg width={580} height={170} viewBox="0 0 580 170" style={{ display: "block", opacity: 1 - off }}>
          {[150, 290, 430].map((x, i) => (
            <path key={i} d={`M${x} 14 q 26 34 0 68 t 0 68`} fill="none" stroke="#3E9BE0" strokeWidth={11} strokeLinecap="round" strokeDasharray="70 80" strokeDashoffset={-(rt * 240 + i * 50)} />
          ))}
