export const Solare: React.FC<{ short?: boolean }> = ({ short = false }) => {
  const tNew = useCurrentFrame() / SLR_FPS - LEAD;
  const warp = short ? WARP30 : WARP;
  const t = warp ? interpolate(tNew, warp.map((p) => p[0]), warp.map((p) => p[1]), cl) : tNew;
  const T7 = short ? T7L - SKIP : T7L, t2 = short ? t + SKIP : t;
  // trocas de cena, cada uma de um jeito: folha que sobe · faixa inclinada · íris saindo do sol · empurrão lateral ·
  // recuo com fusão · duas metades · círculo
  const sheet = interpolate(t, [T1 - 0.28, T1 + 0.22], [0, 1], { ...cl, easing: OUT });
  const band = interpolate(t, [T2 - 0.3, T2 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const iris = interpolate(t, [T3 - 0.24, T3 + 0.28], [0, 1], { ...cl, easing: INOUT });
  const push = interpolate(t, [T4 - 0.26, T4 + 0.22], [0, 1], { ...cl, easing: INOUT });
  const zoomT = interpolate(t, [T5 - 0.22, T5 + 0.2], [0, 1], { ...cl, easing: INOUT });
  const split = interpolate(t, [T6 - 0.2, T6 + 0.22], [0, 1], { ...cl, easing: INOUT });
  const circ = interpolate(t, [T7 - 0.2, T7 + 0.32], [0, 1], { ...cl, easing: INOUT });
  return (
    <Real.Provider value={tNew}>
    <AbsoluteFill style={{ background: WHITE }}>
      {t < T1 + 0.25 ? (
        <AbsoluteFill style={{ transform: `scale(${(1 - 0.06 * sheet).toFixed(4)})` }}><Hook t={t} /></AbsoluteFill>
      ) : null}
      {t >= T1 - 0.3 && t < T2 + 0.02 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - sheet) * 1920).toFixed(1)}px)`, borderRadius: `${((1 - sheet) * 90).toFixed(0)}px ${((1 - sheet) * 90).toFixed(0)}px 0 0`, overflow: "hidden" }}><Conta t={t} /></AbsoluteFill>
      ) : null}
      {t >= T2 && t < T3 + 0.3 ? <Calor t={t} /> : null}
      {/* faixa inclinada âmbar cobre a troca da conta para o dia quente */}
      {t >= T2 - 0.32 && t < T2 + 0.32 ? (
        <div style={{ position: "absolute", left: 540 - 1000, top: -500, width: 2000, height: 2920, background: AMBER, transform: `rotate(18deg) translateX(${((band - 0.5) * 2 * 2700).toFixed(1)}px)` }} />
      ) : null}
      {t >= T3 - 0.26 && t < T4 + 0.25 ? (
        <AbsoluteFill style={{ clipPath: t < T3 + 0.3 ? `circle(${(iris * 2300).toFixed(0)}px at 540px 1500px)` : undefined, transform: `translateX(${(-push * 1080).toFixed(1)}px)` }}><Marca t={t} /></AbsoluteFill>
      ) : null}
      {t >= T4 - 0.28 && t < T5 + 0.22 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1080).toFixed(1)}px) scale(${(1 - 0.12 * zoomT).toFixed(4)})`, opacity: 1 - zoomT }}><Casa t={t} /></AbsoluteFill>
      ) : null}
      {t >= T5 - 0.22 && t < T6 + 0.24 ? (
        <AbsoluteFill style={{ opacity: t < T5 + 0.22 ? zoomT : 1, transform: `scale(${(1.12 - 0.12 * zoomT).toFixed(4)})` }}><Noventa t={t} /></AbsoluteFill>
      ) : null}
      {t >= T6 - 0.22 && t < T7 + 0.34 ? (
        <AbsoluteFill style={{ clipPath: `inset(${((1 - split) * 50).toFixed(2)}% 0 ${((1 - split) * 50).toFixed(2)}% 0)` }}><Orcamento t={t2} ask={short ? "Solicite agora" : undefined} /></AbsoluteFill>
      ) : null}
      {t >= T7 - 0.22 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(circ * 2300).toFixed(0)}px at 540px 1100px)` }}><Fecho t={t2} dialAt={short ? [] : undefined} at={short ? [27.05, 26.2, 26.55, 28.2] : undefined} /></AbsoluteFill>
      ) : null}
    </AbsoluteFill>
    </Real.Provider>
  );
};

